(()=>{
const rows=[{"pdb_id": "1UBQ", "title": "STRUCTURE OF UBIQUITIN REFINED AT 1.8 ANGSTROMS RESOLUTION", "method": "X-RAY DIFFRACTION", "deposited_atoms": 660, "polymer_entities": 1, "resolution_angstrom": 1.8, "response_bytes": 9980, "sha256": "ae6dffdc03b6e2b7873f76409fe1727970b25640c367ec62e3de4e9b8a158f1f"}, {"pdb_id": "4HHB", "title": "THE CRYSTAL STRUCTURE OF HUMAN DEOXYHAEMOGLOBIN AT 1.74 ANGSTROMS RESOLUTION", "method": "X-RAY DIFFRACTION", "deposited_atoms": 4779, "polymer_entities": 2, "resolution_angstrom": 1.74, "response_bytes": 26055, "sha256": "a95a79421b90211667e08cc21555acb6e2c384fe882bb7c9b174eadb4e9fdb1a"}, {"pdb_id": "1BNA", "title": "STRUCTURE OF A B-DNA DODECAMER. CONFORMATION AND DYNAMICS", "method": "X-RAY DIFFRACTION", "deposited_atoms": 566, "polymer_entities": 1, "resolution_angstrom": 1.9, "response_bytes": 10270, "sha256": "fbc0fbc995c879dd08ade56d6d866a5f65f88cf99fa7b169eee7af1d404fcc55"}, {"pdb_id": "1D3Z", "title": "UBIQUITIN NMR STRUCTURE", "method": "SOLUTION NMR", "deposited_atoms": 602, "polymer_entities": 1, "resolution_angstrom": null, "response_bytes": 9097, "sha256": "b7cbea751162966d06e63c6df271ad046291ad777b9b924891429f8e79c809bd"}];const zh=document.documentElement.lang.startsWith('zh');const q=id=>document.getElementById('P25-'+id);const params={entry:'1UBQ',field:'deposited_atoms',method:'all'};const paths={deposited_atoms:'rcsb_entry_info.deposited_atom_count',polymer_entities:'rcsb_entry_info.polymer_entity_count',resolution_angstrom:'rcsb_entry_info.resolution_combined[0]'};let result={};
function render(){let selected=rows.filter(r=>params.method==='all'||(params.method==='nmr'?r.method==='SOLUTION NMR':r.method==='X-RAY DIFFRACTION'));if(!selected.some(r=>r.pdb_id===params.entry))params.entry=selected[0].pdb_id;const r=selected.find(r=>r.pdb_id===params.entry);['entry','field','method'].forEach(k=>q(k).value=params[k]);q('entry').querySelectorAll('option').forEach(o=>o.disabled=!selected.some(r=>r.pdb_id===o.value));const value=r[params.field];q('record').textContent=r.pdb_id+' · '+r.method+' · '+r.title;q('path').textContent=paths[params.field];const fieldKey=paths[params.field].split('.')[1].replace('[0]','');q('json').textContent=JSON.stringify({rcsb_id:r.pdb_id,exptl:[{method:r.method}],rcsb_entry_info:value===null?{}:{[fieldKey]:params.field==='resolution_angstrom'?[value]:value}},null,2);let top=Math.max(...selected.map(r=>r[params.field]??0));let step=params.field==="resolution_angstrom"?.5:(params.field==="polymer_entities"?1:1000);let max=Math.max(step,Math.ceil(top/step)*step);let s='<rect width="660" height="340" fill="#faf9f5"/>';const title=q('field').selectedOptions[0].textContent;s+='<text x="20" y="27" fill="#172534" font-size="20">'+title+'</text>';for(let j=0;j<=max/step;j++){let x=110+j*step/max*480;s+='<path d="M'+x+' 45V285" stroke="#dce3e6"/><text x="'+x+'" y="310" text-anchor="middle" font-size="19">'+(j*step).toLocaleString(undefined,{maximumFractionDigits:2})+'</text>'}selected.forEach((r,i)=>{let y=70+i*55;let v=r[params.field];s+='<g data-entry="'+r.pdb_id+'" style="cursor:pointer"><text x="16" y="'+(y+5)+'" fill="#172534" font-size="19">'+r.pdb_id+'</text><rect x="110" y="'+(y-13)+'" width="'+(v===null?0:v/max*480)+'" height="25" fill="'+(r.pdb_id===params.entry?'#b4482e':'#205b8c')+'"/><text x="'+(v===null?115:115+v/max*480)+'" y="'+(y+5)+'" font-size="19" fill="#172534">'+(v===null?(zh?'无此指标':'not available'):v)+'</text></g>'});q('chart').innerHTML=s;q('chart').querySelectorAll('[data-entry]').forEach(e=>e.addEventListener('click',()=>{params.entry=e.dataset.entry;render()}));q('table').innerHTML=selected.map(r=>'<tr'+(r.pdb_id===params.entry?' style="background:#edf2f4"':'')+'><td>'+r.pdb_id+'</td><td>'+r.method+'</td><td>'+(r[params.field]===null?'—':r[params.field])+'</td></tr>').join('');result={...params,value,count:selected.length,visible_ids:selected.map(r=>r.pdb_id),path:paths[params.field]};}
['entry','field','method'].forEach(k=>q(k).addEventListener('change',()=>{params[k]=q(k).value;render()}));const reset=()=>{Object.assign(params,{entry:'1UBQ',field:'deposited_atoms',method:'all'});render()};q('reset').addEventListener('click',reset);window.CourseLab={reset,state:()=>({...result}),set:p=>{for(let k of ['entry','field','method'])if(p[k]!==undefined&&[...q(k).options].some(o=>o.value===p[k]))params[k]=p[k];render();return {...result}},destroy:()=>{}};render();})();